"""Paged full-log inspector. Deliberately separate from the physical rollout viewer."""

LOG_HTML = r"""<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>nuPlan · 完整原始日志</title>
<style>*{box-sizing:border-box}body{margin:0;background:#edf2f5;color:#203549;font:14px/1.6 system-ui,sans-serif}header{padding:20px 26px;background:white;border-bottom:1px solid #cbd7df}h1{font-size:25px;margin:5px 0}a{color:#087b83}main{padding:18px;display:grid;grid-template-columns:minmax(500px,1fr) 330px;gap:18px}.panel{background:white;border:1px solid #cfdae1;border-radius:10px;padding:16px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap}button,select,input{font:inherit;border:1px solid #b4c9d3;border-radius:5px;padding:7px;background:white}button{cursor:pointer}button:hover{background:#e6f5f4}#view{display:block;width:100%;height:590px;background:#0e2031;border-radius:8px;margin:12px 0;touch-action:none}#timeline{width:100%;padding:0}#overview{width:100%;height:65px;background:#edf5f7;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 monospace}.note{color:#755a22;background:#fff7e5;padding:10px 16px}.small{font-size:12px;color:#61798a}#status{font-weight:600}#events{max-height:250px;overflow:auto}#events button{display:block;width:100%;text-align:left;margin:4px 0}.legend{display:flex;gap:15px}#actor{width:100%}#error{color:#ad2438}#anchors a{margin-right:10px}h2{font-size:16px}#seekSeconds{width:95px}@media(max-width:900px){main{grid-template-columns:1fr}#view{height:450px}}</style>
<header><a href="../../index.html">← 场景图库</a><h1>完整原始日志 · BEV</h1><div id="identity">加载清单…</div><p class="small">逐帧源标注回放；所有对象均按日志显示，不是受控仿真，也没有计算 PDM、碰撞责任或安全通过率。</p></header>
<div class="note" id="mapNotice">完整保留当前 DB 的原始时间轴，不拼接不连续的其他 DB。地图仅覆盖已编译窗口附近，空白处不代表没有道路。标注缺失按缺失显示，不自动推演成物理离场；可选中对象检查全部标注区间。</div>
<main><section class="panel"><div class="toolbar"><button id="play">播放</button><button id="reset">从头</button><button id="ego">跟随自车</button><button id="fit">查看全程</button><label>倍率 <select id="speed"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option><option value="4">4×</option></select></label><label><input type="checkbox" id="follow" checked>跟随选中对象</label></div>
<canvas id="view" aria-label="原始日志全对象俯视图，可点击选车、拖动和缩放"></canvas><div id="status"></div><input id="timeline" type="range" min="0" max="0" value="0" aria-label="完整日志时间轴"><canvas id="overview" aria-label="全程对象数量和当前时刻"></canvas>
<div class="toolbar"><label>跳至秒 <input id="seekSeconds" type="number" min="0" step="0.05" value="0"></label><button id="seek">跳转</button><a id="permalink">当前对象与时刻链接</a></div><p class="legend"><span style="color:#078c83">■ 自车</span><span style="color:#ae7c23">■ 车辆</span><span style="color:#a45ba8">■ 行人 / 自行车</span><span style="color:#718995">■ 其他物体</span></p><p id="gap" class="note" hidden></p><p id="error"></p></section>
<aside><section class="panel"><h2>选择对象</h2><input id="actorSearch" type="search" placeholder="输入 token 或类别筛选" aria-label="筛选对象"><select id="actor" aria-label="选择对象"></select><pre id="details"></pre><h2>源标注区间</h2><div id="events"></div><p class="small">区间首尾是源帧证据；中断原因可能是遮挡、感知覆盖或漏标，不能仅由此认定物理离场。</p></section><section class="panel" style="margin-top:16px"><h2>本日志的仿真窗口</h2><div id="anchors"></div><p class="small">进入各窗口可对照实际动作与9秒源参考；完整原始播放没有把短仿真拼接成长期闭环。</p><a href="manifest.json">完整数据索引与分块哈希</a><pre id="signals"></pre></section></aside></main>
<script>
const $=id=>document.getElementById(id),canvas=$('view'),ctx=canvas.getContext('2d');
let M,frame=0,selected=0,current=null,cache=new Map(),pending=new Map(),revision=0,playing=false,lastWall=0,clock=0,cx=0,cy=0,scale=5,drag=null,requestedFrame=0,appliedRevision=0,pumpPromise=null,loading=false,resumeAfterSeek=false;
for(const el of document.querySelectorAll('button,input,select'))el.disabled=true;
const seconds=i=>(M.timestamps_us[i]-M.timestamps_us[0])/1e6;
function atTime(t){let lo=0,hi=M.frame_count-1;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(seconds(mid)<=t)lo=mid;else hi=mid-1;}return lo;}
async function chunk(index){if(cache.has(index)){const x=cache.get(index);cache.delete(index);cache.set(index,x);return x;}if(pending.has(index))return pending.get(index);const request=(async()=>{const spec=M.chunks[index],response=await fetch(spec.path);if(!response.ok)throw Error('分块读取失败 '+response.status);const data=await response.json();if(data.start!==spec.start||data.frames.length!==spec.count)throw Error('分块身份/长度不匹配');cache.set(index,data);while(cache.size>3)cache.delete(cache.keys().next().value);return data;})();pending.set(index,request);try{return await request;}finally{pending.delete(index);}}
function play(value){playing=value;resumeAfterSeek=!!(value&&loading);$('play').textContent=playing?'暂停':'播放';lastWall=performance.now();clock=M?seconds(frame):0;}
function seek(index){requestedFrame=Math.max(0,Math.min(M.frame_count-1,Math.round(index)));revision++;loading=true;if(!pumpPromise)pumpPromise=loadLatest();return pumpPromise;}
async function loadLatest(){try{while(appliedRevision!==revision){const index=requestedFrame,ticket=revision;try{const data=await chunk(Math.floor(index/M.chunk_size));if(ticket!==revision)continue;const next=data.frames[index-data.start];if(next.index!==index||next.timestamp_us!==M.timestamps_us[index])throw Error('源帧身份不匹配');frame=index;current=next;appliedRevision=ticket;$('timeline').value=frame;$('seekSeconds').value=seconds(frame).toFixed(3);$('error').textContent='';if(playing&&resumeAfterSeek){clock=seconds(frame);lastWall=performance.now();resumeAfterSeek=false;}draw();info();}catch(error){if(ticket===revision){appliedRevision=ticket;play(false);$('error').textContent=error.message;}}}}finally{loading=false;pumpPromise=null;}}

function position(p){return [canvas.width/2+(p[1]-cx)*scale,canvas.height/2-(p[2]-cy)*scale];}
function resize(){const r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width);canvas.height=Math.round(r.height);draw();}
function draw(){if(!M||!current)return;const chosen=current.objects.find(p=>p[0]===selected);if($('follow').checked&&chosen){cx=chosen[1];cy=chosen[2];}ctx.clearRect(0,0,canvas.width,canvas.height);ctx.lineWidth=1;
 for(const road of M.map_lines){ctx.strokeStyle=road.kind===6?'#8ca9b7':'#59768b';ctx.beginPath();road.points.forEach((p,i)=>{const q=position([0,...p]);i?ctx.lineTo(...q):ctx.moveTo(...q);});ctx.stroke();}
 ctx.strokeStyle='#366e77';ctx.beginPath();M.ego_path.forEach((p,i)=>{const q=position([0,...p]);i?ctx.lineTo(...q):ctx.moveTo(...q);});ctx.stroke();
 for(const p of current.objects){const [x,y]=position(p);if(x<-60||y<-60||x>canvas.width+60||y>canvas.height+60)continue;const kind=M.actors[p[0]].kind;ctx.save();ctx.translate(x,y);ctx.rotate(-p[3]);ctx.fillStyle=p[0]===0?'#55d4c4':kind==='vehicle'?'#deb46c':['pedestrian','bicycle'].includes(kind)?'#dca0e2':'#8c9fac';ctx.fillRect(-p[4]*scale/2,-p[5]*scale/2,p[4]*scale,p[5]*scale);if(p[0]===selected){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.strokeRect(-p[4]*scale/2-3,-p[5]*scale/2-3,p[4]*scale+6,p[5]*scale+6);}ctx.restore();}
 ctx.fillStyle='#d9ecf6';ctx.fillText('原始日志 · 无控制器 / 无碰撞评定 · '+(20*scale).toFixed(0)+' px = 20 m',15,24);
 const o=$('overview');o.width=Math.round(o.getBoundingClientRect().width);o.height=65;const c=o.getContext('2d'),max=Math.max(...M.counts);c.strokeStyle='#148a91';c.beginPath();M.counts.forEach((n,i)=>{const x=seconds(i)/M.duration_seconds*o.width,y=60-n/max*52;i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();c.strokeStyle='#dd8b30';c.beginPath();c.moveTo(seconds(frame)/M.duration_seconds*o.width,0);c.lineTo(seconds(frame)/M.duration_seconds*o.width,65);c.stroke();}
function updateLink(){const u=new URL(location.href);u.searchParams.set('frame',frame);u.searchParams.set('actor',M.actors[selected].id);$('permalink').href=u.href;}
function info(){const actor=M.actors[selected],p=current.objects.find(p=>p[0]===selected);$('status').textContent=seconds(frame).toFixed(3)+' / '+M.duration_seconds.toFixed(3)+' 秒 · 源帧 '+(frame+1)+' / '+M.frame_count+' · 当前 '+current.objects.length+' 个对象';$('details').textContent=actor.id+'\n类别：'+actor.kind+'\n控制归属：源日志回放\n当前源标注：'+(p?'存在':'缺失；不外推位置')+'\n'+(p?'局部中心 XY：'+p[1].toFixed(2)+', '+p[2].toFixed(2)+' m\n尺寸：'+p[4].toFixed(2)+' × '+p[5].toFixed(2)+' m\n源 DB vx / vy：'+p[8]+', '+p[9]:'')+'\nLidar timestamp：'+current.timestamp_us+'\nEgo pose timestamp：'+current.ego_pose_timestamp_us+'\n帧 token：'+current.token;$('signals').textContent='源交通灯（未执行路权规则）\n'+current.signals.map(x=>x.join(': ')).join('\n');$('gap').hidden=!M.gaps_before_frames.includes(frame);$('gap').textContent='本帧之前存在源时间缺口；没有插值或伪造中间状态。';updateLink();}
function actorOptions(){const q=$('actorSearch').value.trim().toLowerCase();$('actor').replaceChildren();M.actors.forEach((a,i)=>{if(i===selected||(a.id+' '+a.kind).toLowerCase().includes(q)){const o=document.createElement('option');o.value=i;o.textContent=a.id+' · '+a.kind;$('actor').append(o);}});$('actor').value=selected;}
function selectActor(index){selected=index;actorOptions();$('events').replaceChildren();for(const [a,b]of M.actors[index].intervals){const button=document.createElement('button');button.textContent=seconds(a).toFixed(3)+'–'+seconds(b).toFixed(3)+' s · '+(b-a+1)+' 帧';button.onclick=()=>{play(false);seek(a);};$('events').append(button);}draw();if(current)info();}
$('play').onclick=()=>play(!playing);$('reset').onclick=()=>{play(false);seek(0);};$('timeline').oninput=()=>{play(false);seek(Number($('timeline').value));};$('seek').onclick=()=>{const t=Number($('seekSeconds').value);if(Number.isFinite(t)){play(false);seek(atTime(Math.max(0,Math.min(M.duration_seconds,t))));}};$('actorSearch').oninput=actorOptions;$('actor').onchange=()=>selectActor(Number($('actor').value));$('ego').onclick=()=>{$('follow').checked=true;scale=5;selectActor(0);};$('follow').onchange=draw;
$('fit').onclick=()=>{$('follow').checked=false;let xs=M.ego_path.map(p=>p[0]),ys=M.ego_path.map(p=>p[1]);const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);cx=(x0+x1)/2;cy=(y0+y1)/2;scale=Math.min(canvas.width/(x1-x0+100),canvas.height/(y1-y0+100));draw();};
canvas.onwheel=e=>{e.preventDefault();scale=Math.max(.1,Math.min(30,scale*Math.exp(-e.deltaY*.001)));draw();};canvas.onpointerdown=e=>{drag={x:e.offsetX,y:e.offsetY,cx,cy,moved:false};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){if(Math.hypot(e.offsetX-drag.x,e.offsetY-drag.y)>4)drag.moved=true;if(drag.moved){$('follow').checked=false;cx=drag.cx-(e.offsetX-drag.x)/scale;cy=drag.cy+(e.offsetY-drag.y)/scale;draw();}}};canvas.onpointerup=e=>{if(drag&&!drag.moved&&current){let best=null,d=18;for(const p of current.objects){const [x,y]=position(p),n=Math.hypot(x-e.offsetX,y-e.offsetY);if(n<d){d=n;best=p[0];}}if(best!==null)selectActor(best);}drag=null;};$('overview').onclick=e=>{if(!M||!current)return;play(false);seek(atTime(e.offsetX/$('overview').clientWidth*M.duration_seconds));};
async function animate(now){if(loading){lastWall=now;}else if(playing&&M){clock+=(now-lastWall)/1000*Number($('speed').value);lastWall=now;const next=atTime(clock);if(next!==frame){await seek(next);lastWall=performance.now();}if(clock>=M.duration_seconds)play(false);}requestAnimationFrame(animate);}requestAnimationFrame(animate);window.addEventListener('resize',resize);
(async()=>{try{const response=await fetch('manifest.json');if(!response.ok)throw Error('清单读取失败');M=await response.json();if(M.mode!=='raw_source_only'||M.status!=='complete')throw Error('清单不是完整源回放');if(M.map_scope==='full_log_object_extent_plus80m')$('mapNotice').textContent='地图覆盖本日志全部对象的观测范围并外扩80米，来自同城市GPKG车道中心线与可行驶区域边界；非自车轨迹替代。边界外未声明支持；标注中断不等于物理离场。';$('identity').textContent=M.map_name+' · '+M.source_log+' · '+M.frame_count+' 帧 · '+M.duration_seconds.toFixed(3)+' 秒 · '+M.actors.length+' 个独立 ID';$('timeline').max=M.frame_count-1;$('seekSeconds').max=M.duration_seconds;for(const a of M.anchors){const p=document.createElement('p'),button=document.createElement('button');button.textContent=a.id+' @ '+seconds(a.frame).toFixed(2)+'s';button.onclick=()=>{play(false);seek(a.frame);};p.append(button);for(const [url,label]of [[a.source,'9秒参考'],[a.diagnostic,'实际诊断']]){const link=document.createElement('a');link.href=url;link.textContent=label;p.append(link);}$('anchors').append(p);}const q=new URLSearchParams(location.search);selected=Math.max(0,M.actors.findIndex(a=>a.id===q.get('actor')));selectActor(selected);resize();await seek(Number(q.get('frame'))||0);if(current)for(const el of document.querySelectorAll('button,input,select'))el.disabled=false;}catch(error){$('error').textContent=error.message;}})();
</script></html>"""
